import faulthandler
import hashlib
import json
from pathlib import Path
import sqlite3
import tempfile
import unittest

import config
from views import check_demo


def catalogue_counts(connection):
    """Measure public and private row counts independently of the published manifest."""
    statements = {
        'series': 'SELECT COUNT(*) FROM series',
        'events': 'SELECT COUNT(*) FROM events',
        'website': "SELECT COUNT(*) FROM event_provenance WHERE kind='website'",
        'projected': "SELECT COUNT(*) FROM event_provenance WHERE kind='projected'",
        'private_archive_rows': '''SELECT (SELECT COUNT(*) FROM training_history)
            + (SELECT COUNT(*) FROM training_imports)''',
        'copied_user_profiles': 'SELECT COUNT(*) FROM users',
    }
    counts = {}
    for key, statement in statements.items():
        counts[key] = connection.execute(statement).fetchone()[0]
    counts['masked_series'] = connection.execute('SELECT COUNT(*) FROM series WHERE title=?',
                                               (config.UNREVIEWED_ACTIVITY_TITLE,)).fetchone()[0]
    counts['masked_projected_events'] = connection.execute('''SELECT COUNT(*) FROM events e
        JOIN series s ON s.id=e.series_id JOIN event_provenance p ON p.event_id=e.id
        WHERE s.title=? AND p.kind='projected' ''',
        (config.UNREVIEWED_ACTIVITY_TITLE,)).fetchone()[0]
    return counts


def checked_seed():
    """Require the committed manifest to describe the actual reviewed starter binary."""
    seed = config.PUBLIC_UNISPORT_SEED
    content = seed.read_bytes()
    manifest = json.loads(seed.with_name('unisport_manifest.json').read_text(encoding='utf-8'))
    connection = sqlite3.connect(seed.resolve().as_uri() + '?mode=ro', uri=True)
    try:
        connection.execute('PRAGMA foreign_keys = 1')
        expected = catalogue_counts(connection)
        first, last = connection.execute('''SELECT MIN(substr(start_time,1,10)),
            MAX(substr(start_time,1,10)) FROM events''').fetchone()
        catalogue_id = connection.execute(
            "SELECT value FROM app_settings WHERE key='catalogue_id'").fetchone()[0]
        private_counts = connection.execute('''SELECT
            (SELECT COUNT(*) FROM clubs), (SELECT COUNT(*) FROM user_directions),
            (SELECT COUNT(*) FROM favorites), (SELECT COUNT(*) FROM interactions),
            (SELECT COUNT(*) FROM friendships), (SELECT COUNT(*) FROM invitations),
            (SELECT COUNT(*) FROM import_log)''').fetchone()
        valid_database = (connection.execute('PRAGMA integrity_check').fetchone()[0] == 'ok'
                          and not connection.execute('PRAGMA foreign_key_check').fetchall())
    finally:
        connection.close()
    if (manifest['file'] != seed.name or manifest['bytes'] != len(content)
            or manifest['sha256'] != hashlib.sha256(content).hexdigest()
            or manifest['counts'] != expected or manifest['catalogue_id'] != catalogue_id
            or manifest['first_date'] != first or first != '2026-11-16'
            or manifest['last_date_inclusive'] != last or last != '2027-07-31'
            or not 0 < expected['events'] <= config.MAX_CATALOGUE_EVENTS
            or expected['events'] != expected['website'] + expected['projected']
            or expected['private_archive_rows'] or expected['copied_user_profiles']
            or any(private_counts) or not valid_database
            or manifest['availability'] != 'unknown'
            or manifest['private_source_files_included'] is not False):
        raise ValueError('The published starter does not match its reviewed manifest.')
    return seed, content


def main():
    """Run the actual published seed against temporary writable files and an offline club feed."""
    original_seed, original_bytes = checked_seed()
    manifest_bytes = original_seed.with_name('unisport_manifest.json').read_bytes()
    with tempfile.TemporaryDirectory(prefix='weekwise-starter-acceptance-') as directory:
        check_demo.isolate_paths(Path(directory) / 'data')
        config.PUBLIC_UNISPORT_SEED.parent.mkdir(parents=True, exist_ok=True)
        config.PUBLIC_UNISPORT_SEED.write_bytes(original_bytes)
        config.PUBLIC_UNISPORT_SEED.with_name('unisport_manifest.json').write_bytes(manifest_bytes)
        config.USE_PUBLIC_STARTER = True
        config.UNICLUBS_FEED_ENABLED = True
        # Defaults bind on import, so load the scenario only after isolating the published seed.
        from views import starter_scenario
        starter_scenario.StarterScenario.original_seed = original_seed
        starter_scenario.StarterScenario.original_bytes = original_bytes
        starter_scenario.StarterScenario.expected_manifest = json.loads(manifest_bytes)
        suite = unittest.defaultTestLoader.loadTestsFromTestCase(starter_scenario.StarterScenario)
        faulthandler.dump_traceback_later(150)
        try:
            result = unittest.TextTestRunner(verbosity=2).run(suite)
        finally:
            faulthandler.cancel_dump_traceback_later()
        return 0 if result.wasSuccessful() else 1


if __name__ == '__main__':
    raise SystemExit(main())
